package com.kioskmdm; import android.app.*;import android.content.*;import android.graphics.Color;import android.widget.*;
public final class UI { static LinearLayout root(Activity a,String title){LinearLayout l=new LinearLayout(a);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,32,32,32); TextView t=new TextView(a);t.setText(title);t.setTextSize(26);t.setTextColor(Color.BLACK);t.setPadding(0,0,0,24);l.addView(t);return l;} static Button b(Activity a,String s){Button b=new Button(a);b.setText(s);return b;} static void msg(Context c,String s){Toast.makeText(c,s,Toast.LENGTH_SHORT).show();}}